  he:{"wholeUnitsDefaultHint":"מחיל יחידות שלמות בלבד לפני הניתוח. פיזור אוטומטי מתחשב בגודל היחידה: יחידה שלמה אחת יכולה לעבור את האחוז האוטומטי למועמד אם היא מתאימה טוב יותר ליעד הסיכון/האמינות; מגבלה ידנית נשארת קשיחה.","deploymentWhy":"למה הסכום הזה","riskConfidenceTarget":"יעד סיכון/אמינות","strongestEligibleSignal":"האות המתאים החזק ביותר","allocationTierFull":"הקצאה מלאה","allocationTierStaged":"הקצאה מדורגת","riskDeploymentMultiplier":"מכפיל השקעה לפי סיכון","wholeUnitAdjustment":"התאמה ליחידות שלמות","capReducedTarget":"מגבלות פיזור/מועמד הפחיתו את היעד","wholeUnitAboveBudget":"יחידה שלמה אחת חורגת מהתקציב הזמין לאחר רזרבת המזומן.","wholeUnitAboveExplicitCap":"יחידה שלמה אחת חורגת מהמגבלה המפורשת שלך למועמד.","wholeUnitNotSelected":"יחידה שלמה לא התאימה מספיק קרוב ליעד הסיכון/האמינות הנוכחי."},
