    if(assetFee&&changedName!=="asset_fee_quantity")assetFee.value=this.inputUnitNumber(assetDerived.feeQuantity);
    if(assetFeePct&&changedName!=="asset_fee_percent")assetFeePct.value=Number.isFinite(assetDerived.feePercent)?Number(assetDerived.feePercent).toFixed(4):"";

