    const get=name=>form.querySelector(`[name="${name}"]`);
    const qtyEl=get("sell_quantity"), unitEl=get("sell_price"), grossEl=get("gross_sale_total"), costEl=get("transaction_cost_total"), proceedsEl=get("proceeds_total");
    const qty=draftNumber(qtyEl?.value);
    let unit=draftNumber(unitEl?.value), gross=draftNumber(grossEl?.value), costs=draftNumber(costEl?.value), proceeds=draftNumber(proceedsEl?.value);
    const rate=Number.isFinite(Number(draft.tradeToSettlement))&&Number(draft.tradeToSettlement)>0?Number(draft.tradeToSettlement):NaN;
    if(changedName==="gross_sale_total")draft.tradeMode="total";
    else if(changedName==="sell_price")draft.tradeMode="unit";
    if(qty!==null&&qty>0){
      if(draft.tradeMode==="total"&&gross!==null)unit=gross/qty;
      else if(unit!==null)gross=unit*qty;
      else if(gross!==null)unit=gross/qty;
    }
    const detailed=["platform","bank","exchange","tax","other"].reduce((sum,key)=>sum+(draftNumber(get(`cost_${key}`)?.value)||0),0);
    if(changedName.startsWith("cost_")){
      costs=detailed;
      if(costEl)costEl.value=this.inputMoneyNumber(costs);
    }
    const tradeCurrency=this.quoteCurrency(draft.asset?.currency||this._portfolio?.base_currency||"EUR")||"EUR";
    const settlementCurrency=this.settlementCurrencyForTrade(get("settlement_currency")?.value||tradeCurrency)||"EUR";
    const grossSettlement=gross!==null&&Number.isFinite(rate)?gross*rate:null;
    if(changedName==="proceeds_total"){
      if(grossSettlement!==null&&proceeds!==null)costs=Math.max(0,grossSettlement-proceeds);
    }else{
      if(costs===null)costs=detailed;
      if(grossSettlement!==null&&costs!==null)proceeds=Math.max(0,grossSettlement-costs);
    }
    if(unitEl&&changedName!=="sell_price")unitEl.value=this.inputPriceNumber(unit);
    if(grossEl&&changedName!=="gross_sale_total")grossEl.value=this.inputMoneyNumber(gross);
    if(costEl&&changedName!=="transaction_cost_total")costEl.value=this.inputMoneyNumber(costs);
    if(proceedsEl&&changedName!=="proceeds_total")proceedsEl.value=this.inputMoneyNumber(proceeds);
    const holding=(this._portfolio?.holdings||[]).find(h=>h.id===draft.holdingId);
