  async changeLanguage(language){
    const next=language==="auto"?"auto":localeKey(language);
    if(next!=="auto"&&!I18N[next])return;
    const previous=this._preferredLang;
    this._preferredLang=next;
    if(this._portfolio)this._portfolio={...this._portfolio,language:next};
    this.applyLanguage(next==="auto"?this._haLang:next);
    // Optimistic render makes the entire panel switch language immediately.
    // The preference is then persisted privately for the authenticated HA user.
    this.render();
    try{
      const saved=await this.call({type:"investment/set_preferences",language:next});
      if(this._portfolio)this._portfolio={...this._portfolio,language:saved.language||next};
    }catch(e){
      this._preferredLang=previous;
      if(this._portfolio)this._portfolio={...this._portfolio,language:previous};
      this.applyLanguage(previous==="auto"?this._haLang:previous);
      this._error=e?.message||String(e);this.render();
    }
  }
